'use strict'

// The player window's only bridge.
//
// Deliberately two functions and nothing else. The page it serves is generated by
// us and loads no remote content, but it is still a document rendering a file
// whose contents came off the internet — so the surface it can reach is one
// number in and one number out, and no path to anything else.

const { contextBridge, ipcRenderer } = require('electron')

contextBridge.exposeInMainWorld('aioPlayer', {
  /** Where this file was last left off, in seconds. */
  resumeAt: () => ipcRenderer.invoke('player:resumeAt'),

  /**
   * Remember the position. Called while playing and once on the way out, because
   * a window closed with the mouse never gets a chance to report anything later.
   */
  remember: (seconds, duration) => ipcRenderer.send('player:position', { seconds, duration }),
})
